def maxSlidingWindow(nums: list[int], k: int) -> list[int]:
    q = deque() # Stores indices
    res = []
    for i, x in enumerate(nums):
        if q and q[0] <= i - k:
            q.popleft() # Evict out of window
        while q and nums[q[-1]] <= x:
            q.pop() # Maintain monotonic decreasing order
        q.append(i)
        if i >= k - 1:
            res.append(nums[q[0]])
    return res

