  constructor() {
    this.arr = [];
  }
  addNum(num) {
    let l = 0, r = this.arr.length;
    while (l < r) {
      const mid = Math.floor((l + r) / 2);
      if (this.arr[mid] < num) l = mid + 1;
      else r = mid;
    }
    this.arr.splice(l, 0, num);
  }
  findMedian() {
    const n = this.arr.length;
    if (n % 2 !== 0) return this.arr[Math.floor(n / 2)];
    return (this.arr[n / 2 - 1] + this.arr[n / 2]) / 2.0;
  }
}

