        Stack<Integer> stack = new Stack<>();
        for (int i = tokens.length - 1; i >= 0; i--) {
            String t = tokens[i];
            if ("+".equals(t) || "-".equals(t) || "*".equals(t) || "/".equals(t)) {
                int a = stack.pop();
                int b = stack.pop();
                if ("+".equals(t)) stack.push(a + b);
                else if ("-".equals(t)) stack.push(a - b);
                else if ("*".equals(t)) stack.push(a * b);
                else if ("/".equals(t)) stack.push(a / b);
            } else {
                stack.push(Integer.parseInt(t));
            }
        }
        return stack.peek();
    }
}

function evalPrefix(tokens) {
