def removeInvalidParentheses(s: str) -> list[str]:
    def is_valid(string):
        count = 0
        for c in string:
            if c == '(': count += 1
            elif c == ')':
                count -= 1
                if count < 0: return False
        return count == 0

    visited = {s}
    q = deque([s])
    res = []
    found = False

    while q:
        curr = q.popleft()
        if is_valid(curr):
            res.append(curr)
            found = True
        if found: continue
        for i in range(len(curr)):
            if curr[i] not in '()': continue
            nxt = curr[:i] + curr[i+1:]
            if nxt not in visited:
                visited.add(nxt)
                q.append(nxt)
    return res

